solution:
"""Design a Stack With Increment Operation — lazy increment array.

`_bump[i]` holds an increment owed to every element at or below index i, which
is pushed down to i-1 when i is popped. That makes `increment` O(1).

Time: O(1) per operation   Space: O(maxSize)
"""


class CustomStack:
    def __init__(self, maxSize: int):
        self._max = maxSize
        self._stack = []
        self._bump = [0] * maxSize

    def push(self, x: int) -> None:
        if len(self._stack) < self._max:
            self._stack.append(x)

    def pop(self) -> int:
        if not self._stack:
            return -1
        i = len(self._stack) - 1
        value = self._stack.pop() + self._bump[i]
        if i:
            self._bump[i - 1] += self._bump[i]
        self._bump[i] = 0
        return value

    def increment(self, k: int, val: int) -> None:
        if self._stack:
            self._bump[min(k, len(self._stack)) - 1] += val
